<script lang="ts">
 import {onMount} from 'svelte';
 import {IconPlus,IconTrash,IconSearch,IconArrowUp,IconArrowDown,IconCopy,IconDeviceFloppy,IconRestore,IconCheck,IconStack2} from '@tabler/icons-svelte';
 import PageHeader from '../components/PageHeader.svelte';
 import {api,type Hero,type Result} from '../types';
 import {itemImage,type Item} from '../lib/build-types';
 import {decodeBuild,encodeBuild,type WorkshopBuild,type WorkshopCategory,type WorkshopItem} from '../lib/hero-build-codec';
 type ShopTab='build'|'weapon'|'vitality'|'spirit';
 let heroes=$state<Hero[]>([]),items=$state<Item[]>([]),heroId=$state(0),name=$state(''),description=$state(''),categories=$state<WorkshopCategory[]>([]),code=$state(''),generated=$state(''),message=$state(''),error=$state(''),loading=$state(true),hasSavedDraft=$state(false);
 let selectedCategory=$state(0),selectedItem=$state<{category:number;index:number}|null>(null),activeTab=$state<ShopTab>('build'),itemQuery=$state('');
 const draftKey='deadlook.buildWorkshop.draft.v1';
 const slots:{key:Exclude<ShopTab,'build'>;label:string}[]=[{key:'weapon',label:'Weapon'},{key:'vitality',label:'Vitality'},{key:'spirit',label:'Spirit'}];
 const currentCategory=$derived(categories[selectedCategory]);
 const currentItem=$derived(selectedItem?categories[selectedItem.category]?.items[selectedItem.index]:undefined);
 const currentItemData=$derived(currentItem?items.find(i=>i.id===currentItem.itemId):undefined);
 const shopItems=$derived(activeTab==='build'?[]:items.filter(i=>i.type==='upgrade'&&i.item_slot_type===activeTab&&i.name.toLowerCase().includes(itemQuery.toLowerCase())).sort((a,b)=>(a.item_tier||0)-(b.item_tier||0)||(a.cost||0)-(b.cost||0)||a.name.localeCompare(b.name)));
 function addCategory(){categories=[...categories,{name:'New Category',description:'',width:3,height:2,items:[]}];selectedCategory=categories.length-1;selectedItem=null;activeTab='build';}
 function chooseCategory(index:number){selectedCategory=index;selectedItem=null;activeTab='build';}
 function patchCategory(index:number,patch:Partial<WorkshopCategory>){categories=categories.map((c,i)=>i===index?{...c,...patch}:c);}
 function removeCategory(index:number){categories=categories.filter((_,i)=>i!==index);selectedCategory=Math.max(0,Math.min(selectedCategory,categories.length-1));selectedItem=null;}
 function moveCategory(index:number,delta:number){const to=index+delta;if(to<0||to>=categories.length)return;const next=[...categories];[next[index],next[to]]=[next[to],next[index]];categories=next;selectedCategory=to;selectedItem=null;}
 function addShopItem(item:Item){if(!categories.length)addCategory();const c=Math.min(selectedCategory,categories.length-1);const target=categories[c];if(!target)return;const row={itemId:item.id,annotation:''};categories=categories.map((cat,i)=>i===c?{...cat,items:[...cat.items,row]}:cat);selectedCategory=c;selectedItem={category:c,index:target.items.length};message=item.name+' added to '+target.name+'.';}
 function patchSelectedItem(patch:Partial<WorkshopItem>){if(!selectedItem)return;const {category,index}=selectedItem;categories=categories.map((c,i)=>i===category?{...c,items:c.items.map((item,j)=>j===index?{...item,...patch}:item)}:c);}
 function removeSelectedItem(){if(!selectedItem)return;const {category,index}=selectedItem;categories=categories.map((c,i)=>i===category?{...c,items:c.items.filter((_,j)=>j!==index)}:c);selectedItem=null;}
 function moveSelectedItem(delta:number){if(!selectedItem)return;const {category,index}=selectedItem;const to=index+delta,rows=[...categories[category].items];if(to<0||to>=rows.length)return;[rows[index],rows[to]]=[rows[to],rows[index]];categories=categories.map((c,i)=>i===category?{...c,items:rows}:c);selectedItem={category,index:to};}
 function itemInBuild(id:number){return categories.reduce((n,c)=>n+c.items.filter(i=>i.itemId===id).length,0);}
 async function generate(){error='';generated='';if(!heroId){error='Choose a hero first.';return false;}if(!name.trim()){error='Enter a build name first.';return false;}if(categories.some(c=>c.items.some(i=>!i.itemId))){error='Choose an item for each added row, or remove the empty row.';return false;}try{generated=await encodeBuild({heroId,name:name.trim(),description,categories});message='Clipboard build code generated.';return true;}catch(e){error=(e as Error).message;return false;}}
 async function copy(){if(!await generate())return;try{await navigator.clipboard.writeText(generated);message='Build code copied to clipboard.';}catch{message='Clipboard permission unavailable. Select and copy the generated code below.';}}
 async function importCode(){error='';try{const b:WorkshopBuild=await decodeBuild(code);heroId=b.heroId;name=b.name;description=b.description;categories=b.categories;selectedCategory=0;selectedItem=null;activeTab='build';message='Build imported and ready to edit.';}catch(e){error=(e as Error).message;}}
 async function paste(){try{code=await navigator.clipboard.readText();await importCode();}catch(e){error=(e as Error).message||'Clipboard read unavailable. Paste the code into the import field.';}}
 function saveDraft(){try{localStorage.setItem(draftKey,JSON.stringify({heroId,name,description,categories}));hasSavedDraft=true;message='Draft saved in this browser.';error='';}catch{error='Could not save a local draft. Check browser storage settings.';}}
 function restoreDraft(){try{const raw=localStorage.getItem(draftKey);if(!raw)throw new Error('No saved draft found in this browser.');const draft=JSON.parse(raw) as Partial<WorkshopBuild>;if(!Number.isInteger(draft.heroId)||!Array.isArray(draft.categories))throw new Error('Saved draft is invalid.');heroId=draft.heroId!;name=typeof draft.name==='string'?draft.name:'';description=typeof draft.description==='string'?draft.description:'';categories=draft.categories;selectedCategory=0;selectedItem=null;activeTab='build';message='Draft restored from this browser.';error='';}catch(e){error=(e as Error).message;}}
 onMount(async()=>{hasSavedDraft=!!localStorage.getItem(draftKey);try{const [h,it]=await Promise.all([api<Result<Hero[]>>('/api/heroes'),api<Result<Item[]>>('/api/finder/items')]);heroes=h.data.filter(x=>x.playable!==false).sort((a,b)=>a.name.localeCompare(b.name));items=it.data;heroId=heroes[0]?.id||0;categories=[{name:'Weapon',description:'',width:3,height:2,items:[]},{name:'Vitality',description:'',width:3,height:2,items:[]},{name:'Spirit',description:'',width:3,height:2,items:[]}];}catch(e){error=(e as Error).message;}finally{loading=false;}});
</script>
<svelte:head><title>Build Workshop · Deadlook</title></svelte:head>
<PageHeader eyebrow="BUILD TOOLS" title="Build Workshop" description="Build a Deadlock item guide visually: organize categories, browse the shop and add items."/>
<div class="page-body"><div class="container-xl">
 <div class="alert alert-info" role="note">Your build is edited in this browser. Generate a clipboard code, paste it into Deadlock, then save or publish it in game. Ability-order data on imported codes is preserved, but editing ability points is not supported yet.</div>
 {#if error}<div class="alert alert-danger" role="alert">{error}</div>{/if}
 <section class="workshop-layout" aria-label="Build editor">
  <aside class="workshop-inspector" aria-label="Build properties">
   <div class="workshop-inspector-header"><span class="workshop-kicker">EDIT BUILD</span><strong>{heroes.find(h=>h.id===heroId)?.name||'Choose a hero'}</strong></div>
   <div class="workshop-inspector-body">
    <label class="form-label" for="workshop-hero">Hero</label><select class="form-select mb-3" id="workshop-hero" bind:value={heroId} disabled={loading}>{#each heroes as hero}<option value={hero.id}>{hero.name}</option>{/each}</select>
    <label class="form-label" for="workshop-name">Build name</label><input class="form-control mb-3" id="workshop-name" bind:value={name} maxlength="128" placeholder="Name your build"/>
    <label class="form-label" for="workshop-description">Build description</label><textarea class="form-control mb-4" id="workshop-description" bind:value={description} rows="3" maxlength="2048" placeholder="What is this build for?"></textarea>
    <div class="workshop-selection-header"><span class="workshop-kicker">SELECTION</span><strong>{currentItemData?.name||currentCategory?.name||'Nothing selected'}</strong></div>
    {#if currentItem && selectedItem}
     <div class="workshop-selected-item">{#if itemImage(currentItemData)}<img src={itemImage(currentItemData)} alt=""/>{/if}<span>{currentItemData?.name||'Item #'+currentItem.itemId}</span></div>
     <label class="form-label" for="selected-item-note">Item annotation</label><textarea id="selected-item-note" class="form-control mb-3" rows="3" value={currentItem.annotation} oninput={e=>patchSelectedItem({annotation:e.currentTarget.value})} placeholder="Optional note"></textarea>
     <div class="d-flex flex-wrap gap-2 mb-3"><button class="btn btn-sm" aria-label="Move selected item up" disabled={selectedItem.index===0} onclick={()=>moveSelectedItem(-1)}><IconArrowUp size={16}/> Move up</button><button class="btn btn-sm" aria-label="Move selected item down" disabled={selectedItem.index===categories[selectedItem.category].items.length-1} onclick={()=>moveSelectedItem(1)}><IconArrowDown size={16}/> Move down</button><button class="btn btn-sm btn-outline-danger ms-auto" onclick={removeSelectedItem}><IconTrash size={16}/> Remove</button></div>
    {:else if currentCategory}
     <label class="form-label" for="selected-category-name">Category name</label><input id="selected-category-name" class="form-control mb-3" value={currentCategory.name} oninput={e=>patchCategory(selectedCategory,{name:e.currentTarget.value})}/>
     <label class="form-label" for="selected-category-description">Category description</label><textarea id="selected-category-description" class="form-control mb-3" rows="3" value={currentCategory.description} oninput={e=>patchCategory(selectedCategory,{description:e.currentTarget.value})} placeholder="Optional buying tips"></textarea>
     <label class="form-check mb-3"><input class="form-check-input" type="checkbox" checked={currentCategory.optional||false} onchange={e=>patchCategory(selectedCategory,{optional:e.currentTarget.checked})}/><span class="form-check-label">Optional category</span></label>
     <div class="row g-2 mb-3"><div class="col-6"><label class="form-label" for="category-width">Width</label><input id="category-width" class="form-control" type="number" min="1" max="8" step="0.5" value={currentCategory.width} oninput={e=>patchCategory(selectedCategory,{width:Math.max(1,Math.min(8,Number(e.currentTarget.value)||1))})}/></div><div class="col-6"><label class="form-label" for="category-height">Height</label><input id="category-height" class="form-control" type="number" min="1" max="8" step="0.5" value={currentCategory.height} oninput={e=>patchCategory(selectedCategory,{height:Math.max(1,Math.min(8,Number(e.currentTarget.value)||1))})}/></div></div>
     <div class="d-flex gap-2"><button class="btn btn-sm" aria-label="Move category up" disabled={selectedCategory===0} onclick={()=>moveCategory(selectedCategory,-1)}><IconArrowUp size={16}/></button><button class="btn btn-sm" aria-label="Move category down" disabled={selectedCategory===categories.length-1} onclick={()=>moveCategory(selectedCategory,1)}><IconArrowDown size={16}/></button><button class="btn btn-sm btn-outline-danger ms-auto" onclick={()=>removeCategory(selectedCategory)}><IconTrash size={16}/> Delete category</button></div>
    {:else}<p class="text-secondary small">Select or add a category to edit its properties.</p>{/if}
   </div>
   <div class="workshop-inspector-actions"><button class="btn btn-primary w-100 mb-2" onclick={copy}><IconCopy size={17}/> Generate &amp; copy game code</button><div class="d-flex gap-2"><button class="btn btn-sm flex-fill" onclick={saveDraft}><IconDeviceFloppy size={16}/> Save draft</button><button class="btn btn-sm flex-fill" onclick={restoreDraft} disabled={!hasSavedDraft}><IconRestore size={16}/> Restore</button></div></div>
  </aside>
  <div class="workshop-main">
   <section class="workshop-board" aria-labelledby="categories-heading">
    <div class="workshop-board-heading"><div><span class="workshop-kicker">BUILD PLAN</span><h2 id="categories-heading">Categories</h2></div><button class="btn btn-sm btn-primary" onclick={addCategory}><IconPlus size={17}/> Add category</button></div>
    {#if categories.length}<div class="workshop-category-list">{#each categories as category,c}
     <article class="workshop-category" class:selected={selectedCategory===c&&!selectedItem}>
      <div class="workshop-category-heading"><button class="workshop-category-title" aria-pressed={selectedCategory===c&&!selectedItem} onclick={()=>chooseCategory(c)}><strong>{category.name||'Untitled category'}</strong>{#if category.description}<span>{category.description}</span>{:else}<span class="text-secondary">Select to edit category details</span>{/if}</button>{#if category.optional}<span class="workshop-optional">OPTIONAL</span>{/if}<div class="workshop-category-actions"><button class="btn btn-sm btn-icon" aria-label={'Move '+category.name+' up'} disabled={c===0} onclick={()=>moveCategory(c,-1)}><IconArrowUp size={15}/></button><button class="btn btn-sm btn-icon" aria-label={'Move '+category.name+' down'} disabled={c===categories.length-1} onclick={()=>moveCategory(c,1)}><IconArrowDown size={15}/></button><button class="btn btn-sm btn-icon text-danger" aria-label={'Delete '+category.name} onclick={()=>removeCategory(c)}><IconTrash size={15}/></button></div></div>
      {#if category.items.length}<div class="workshop-category-items">{#each category.items as row,r}<button class="workshop-build-item" class:active={selectedItem?.category===c&&selectedItem?.index===r} aria-pressed={selectedItem?.category===c&&selectedItem?.index===r} onclick={()=>{selectedCategory=c;selectedItem={category:c,index:r};}}>{#if itemImage(items.find(it=>it.id===row.itemId))}<img src={itemImage(items.find(it=>it.id===row.itemId))} alt="" loading="lazy"/>{:else}<span class="workshop-item-placeholder">{items.find(it=>it.id===row.itemId)?.name?.slice(0,1)||'?'}</span>{/if}<span class="workshop-build-item-name">{items.find(it=>it.id===row.itemId)?.name||'Item #'+row.itemId}</span>{#if row.annotation}<span class="workshop-build-item-note">{row.annotation}</span>{/if}</button>{/each}</div>{:else}<button class="workshop-empty-category" onclick={()=>{chooseCategory(c);activeTab='weapon';}}><IconPlus size={17}/> Choose an item from the shop below</button>{/if}
     </article>
    {/each}</div>{:else}<div class="workshop-empty-board"><IconStack2 size={30}/><strong>No categories yet</strong><span>Add a category to start arranging your build.</span><button class="btn btn-primary" onclick={addCategory}><IconPlus size={17}/> Add category</button></div>{/if}
   </section>
   <section class="workshop-shop" aria-labelledby="shop-heading">
    <div class="workshop-shop-heading"><div><span class="workshop-kicker">ITEM SHOP</span><h2 id="shop-heading">Browse items</h2></div><label class="workshop-search" aria-label="Search items"><IconSearch size={17}/><input id="workshop-item-search" class="form-control" placeholder="Search items…" bind:value={itemQuery}/></label></div>
    <div class="workshop-tabs" role="tablist" aria-label="Build editor sections"><button class:active={activeTab==='build'} role="tab" aria-selected={activeTab==='build'} onclick={()=>activeTab='build'}><IconStack2 size={16}/> Builds</button>{#each slots as slot}<button class:active={activeTab===slot.key} role="tab" aria-selected={activeTab===slot.key} onclick={()=>activeTab=slot.key}>{slot.label}</button>{/each}</div>
    {#if activeTab==='build'}<div class="workshop-shop-prompt">Select a category above, then choose <strong>Weapon</strong>, <strong>Vitality</strong>, or <strong>Spirit</strong> to browse the shop and add items.</div>
    {:else if shopItems.length}<div class="workshop-shop-grid">{#each shopItems as item}<button class="workshop-shop-item" onclick={()=>addShopItem(item)} aria-label={'Add '+item.name+' to '+(currentCategory?.name||'build')}>{#if itemImage(item)}<img src={itemImage(item)} alt="" loading="lazy"/>{:else}<span class="workshop-shop-placeholder">{item.name.slice(0,1)}</span>{/if}<span class="workshop-shop-item-title">{item.name}</span><span class="workshop-shop-item-meta">{item.cost!==undefined?item.cost.toLocaleString()+' souls':''}{item.item_tier?' · Tier '+item.item_tier:''}</span><span class="workshop-add-label"><IconPlus size={13}/> Add{itemInBuild(item.id)?' · '+itemInBuild(item.id):''}</span></button>{/each}</div>
    {:else}<div class="workshop-shop-prompt">{loading?'Loading shop items…':itemQuery?'No items match that search.':'No items are available in this shop category.'}</div>{/if}
   </section>
   <section class="workshop-code-panel" aria-labelledby="code-heading"><div><span class="workshop-kicker">IN-GAME CLIPBOARD</span><h2 id="code-heading">Paste or export build code</h2><p class="text-secondary small">Clipboard codes are version-sensitive. You save or publish the build from inside Deadlock.</p></div><details class="workshop-import"><summary>Import / paste an existing code</summary><label for="build-import" class="form-label mt-3">Build code</label><textarea id="build-import" class="form-control font-monospace mb-2" rows="3" bind:value={code}></textarea><button class="btn btn-sm me-2" onclick={paste}>Paste from clipboard</button><button class="btn btn-sm" onclick={importCode}>Import code</button></details>{#if message}<p role="status" class="text-secondary small mb-2">{message}</p>{/if}<label for="build-output" class="form-label">Generated clipboard code</label><textarea id="build-output" class="form-control font-monospace" rows="3" bind:value={generated} readonly placeholder="Use Generate & copy game code to create a code…"></textarea></section>
  </div>
 </section>
</div></div>
